import pyomo.environ as pyo

DATA = {
    "morphine_per_painkiller": 10,   # mg per painkiller pill
    "morphine_per_sleeping": 6,      # mg per sleeping pill
    "morphine_available": 3000,      # mg total
    "digestive_per_painkiller": 3,   # units per painkiller pill
    "digestive_per_sleeping": 5,     # units per sleeping pill
    "min_painkillers": 50,           # at least this many painkiller pills
    "min_sleeping_fraction": 0.70,   # at least 70% of all pills are sleeping
    "pills": ["painkiller", "sleeping"],
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.pills = pyo.Set(initialize=d["pills"])

    model.make = pyo.Var(model.pills, within=pyo.NonNegativeIntegers, bounds=(0, None))

    def morphine_limit(m):
        return (
            d["morphine_per_painkiller"] * m.make["painkiller"]
            + d["morphine_per_sleeping"] * m.make["sleeping"]
            <= d["morphine_available"]
        )

    model.morphine_limit = pyo.Constraint(rule=morphine_limit)

    def painkiller_minimum(m):
        return m.make["painkiller"] >= d["min_painkillers"]

    model.painkiller_minimum = pyo.Constraint(rule=painkiller_minimum)

    def sleeping_fraction(m):
        # sleeping >= frac * (painkiller + sleeping)  ->  linear:
        # (1 - frac) * sleeping - frac * painkiller >= 0
        return (
            (1 - d["min_sleeping_fraction"]) * m.make["sleeping"]
            - d["min_sleeping_fraction"] * m.make["painkiller"]
            >= 0
        )

    model.sleeping_fraction = pyo.Constraint(rule=sleeping_fraction)

    def objective_rule(m):
        return (
            d["digestive_per_painkiller"] * m.make["painkiller"]
            + d["digestive_per_sleeping"] * m.make["sleeping"]
        )

    model.obj = pyo.Objective(rule=objective_rule, sense=pyo.minimize)

    return model


if __name__ == "__main__":
    m = build_model()
    m.pprint()
